pair F=foot(B,A,C);
draw(A--B--C--cycle);
draw(rightanglemark(A,B,C,8));
draw(B--F,linetype("4 2"));
label("3",waypoint(B--F,0.6),W);

label("$A$",A,SE);
label("$B$",B,N);
label("$C$",C,SW);
label("$F$",F,S);[/asy]

